<script setup>
import {computed,reactive,ref,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {account,passwordValid,fileError} from '../account'
import {session,openModal,logout} from '../session'
import {path} from '../data'
import {locale,languages,applyLocale,t} from '../i18n'
import QRCode from 'qrcode'
import Survey from './Survey.vue'
import Icon from '../components/Icon.vue'
const locationOrigin=location.origin
const referralQr=ref('')
watch(locale,async()=>{referralQr.value=await QRCode.toDataURL(locationOrigin+'/newtrend'+path('/register')+'?ref=DEMO10001',{width:160,margin:1})},{immediate:true})
const route=useRoute(),router=useRouter(),page=computed(()=>route.params.account),id=computed(()=>route.params.id),step=ref(1),sent=ref(false),count=ref(0),error=ref(''),success=ref(''),files=reactive({}),filter=ref("aiQuant.templates.filterAll"),query=ref(''),editing=ref(false),draftName=ref(account.name)
const form=reactive({old:'',password:'',confirm:'',email:'',phone:'',prefix:'+1',code:'',fullName:'',idType:'',idNumber:'',country:'',referral:'',relationship:'',uid:'',proofType:'BANK_STATEMENT',note:''});let countdown
const isFund=computed(()=>page.value==='fund-password'),isPassword=computed(()=>isFund.value||page.value==='change-password'),isBinding=computed(()=>['bind-email','bind-phone'].includes(page.value)),isEmail=computed(()=>page.value==='bind-email')
const title=computed(()=>{const p=page.value;return p==='change-password'?t('profile.changePassword.title'):p==='fund-password'?t('profile.fundPasswordPage.'+(account.fundPasswordSet?'changeTitle':'setTitle')):p==='bind-email'?t('profile.bindEmailPage.'+(account.email?'titleChange':'titleBind')):p==='bind-phone'?t('profile.bindPhonePage.'+(account.phone?'titleChange':'titleBind')):p==='2fa'?t('twoFactor.'+(account.twoFactor?'2faStatus':'bind2fa')):p==='kyc'?t(id.value==='basic'?'kyc.kycTitle':id.value==='advanced'?'kyc.advanced.pageTitle':'kyc.center.title'):p==='referrals'?t('referral.page.title'):p==='joint-account'?t('jointAccount.page.title'):p==='promotions'?t('promotion.list.title'):p==='devices'?t('devices.title'):p==='help-center'?t('profile.helpCenterPage.title'):p==='survey'?t('survey.entry.title'):t('profile.pageTitle')})
const subtitle=computed(()=>{const p=page.value;return p==='change-password'?t('profile.changePassword.subtitle'):p==='fund-password'?t('profile.fundPasswordPage.'+(account.fundPasswordSet?'changeSubtitle':'setSubtitle')):p==='bind-email'?t('profile.bindEmailPage.subtitleChange'):p==='bind-phone'?t('profile.bindPhonePage.subtitleBind'):p==='2fa'?t('twoFactor.bind2faDesc'):p==='kyc'?t(id.value==='basic'?'kyc.kycDesc':id.value==='advanced'?'kyc.advanced.pageDesc':'kyc.center.subtitle'):p==='referrals'?t('referral.page.description'):p==='devices'?t('devices.subtitle'):p==='joint-account'?t('jointAccount.page.description'):p==='promotions'?t('promotion.list.description'):p==='help-center'?t('profile.helpCenterPage.subtitle'):''})
const validPassword=computed(()=>isFund.value?/^\d{6}$/.test(form.password):passwordValid(form.password)),validContact=computed(()=>isEmail.value?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email):/^\d{6,15}$/.test(form.phone))
const security=computed(()=>account.fundPasswordSet&&account.twoFactor?"auth.passwordStrengthHigh":account.fundPasswordSet||account.twoFactor?"auth.passwordStrengthMedium":"auth.passwordStrengthLow")
function setLanguage(l){applyLocale(l);router.replace({path:route.path.replace(/^\/[^/]+/,'/'+l),query:route.query,hash:route.hash})}
function reset(){step.value=1;sent.value=false;count.value=0;error.value='';success.value='';clearInterval(countdown);Object.keys(files).forEach(k=>delete files[k]);for(const k of Object.keys(form))form[k]=k==='prefix'?'+1':k==='proofType'?'BANK_STATEMENT':''}
watch(()=>page.value+'|'+id.value,reset);onUnmounted(()=>clearInterval(countdown))
function passwordSubmit(){error.value='';if(!validPassword.value){error.value=isFund.value?"account.ui.exactly6Digits":"account.ui.checkThePasswordRequirements";return}if(form.password!==form.confirm){error.value="auth.passwordMismatch";return}if(form.old&&form.old===form.password){error.value="profile.fundPasswordPage.passwordSameAsOld";return}if(isFund.value)account.fundPasswordSet=true;form.old=form.password=form.confirm='';success.value=isFund.value?"profile.fundPasswordSet":"profile.changePassword.changed"}
function sendCode(){if(!validContact.value)return;if(isEmail.value&&form.email===account.email){error.value="profile.bindEmailPage.sameAsCurrentEmail";return}sent.value=true;count.value=60;error.value='';clearInterval(countdown);countdown=setInterval(()=>{if(--count.value<=0)clearInterval(countdown)},1000)}
function bind(){if(form.code!=='123456'){error.value="profile.bindEmailPage.invalidVerificationCode";return}if(isEmail.value)account.email=form.email;else account.phone=form.prefix+' '+form.phone;success.value=isEmail.value?"profile.bindEmailPage.changeSuccess":"profile.bindPhonePage.bindSuccess";form.code='';sent.value=false}
function toggle2fa(){if(form.code!=='123456'){error.value="profile.bindEmailPage.invalidVerificationCode";return}account.twoFactor=!account.twoFactor;success.value=account.twoFactor?"twoFactor.boundSuccess":"twoFactor.unbindSuccess";form.code='';error.value=''}
function selectFile(key,e){const file=e.target.files?.[0];error.value=fileError(file,20);if(!error.value)files[key]=file.name;else delete files[key]}
function nextKyc(){if(!form.fullName.trim()||!form.idType||!form.idNumber.trim()||!form.country){error.value="kyc.fillAllFields";return}error.value='';step.value=2}
function submitKyc(){const required=id.value==='advanced'?['handheld','proof']:['front','back','selfie'];if(required.some(k=>!files[k])){error.value="kyc.allUploadsRequired";return}if(id.value==='advanced')account.advanced='pending';else account.kyc='pending';success.value="kyc.advanced.submitSuccess";error.value=''}
function copy(value){navigator.clipboard.writeText(value).then(()=>success.value="c2c.paymentAccount.copied").catch(()=>error.value="common.copyFailed")}
function rename(d){openModal('account-edit',"devices.renameTitle",{value:d.name,onSave:v=>d.name=v})}
function revoke(d){openModal('account-confirm',"devices.revokeTitle",{description:d.current?"devices.revokeCurrentWarning":"devices.revokeBody",onConfirm:()=>{account.devices=account.devices.filter(x=>x.id!==d.id);if(d.current){logout();router.push(path('/login'))}}})}
function saveName(){if(!draftName.value.trim()){error.value="profile.enterUsername";return}account.name=draftName.value.trim();editing.value=false;success.value="profile.usernameUpdated"}
function submitReferral(){if(account.referrer){error.value="referral.bind.errors.alreadyBound";return}if(!form.referral.trim()||form.referral==='DEMO10001'){error.value="referral.bind.errors.invalid";return}account.referrer=form.referral;success.value="referral.bind.success"}
function applyJoint(){if(account.kyc!=='approved'){step.value=2;return}step.value=3}
function submitJoint(){if(!form.relationship||!/^\d{5,12}$/.test(form.uid)||form.uid==='10000001'||!files.relationship){error.value="jointAccount.apply.incomplete";return}account.joint={uid:form.uid,relationship:form.relationship,status:'pending_consent'};step.value=1;success.value="jointAccount.apply.submitted"}
const faqIds=['account1','account2','trade1','trade2','deposit1','deposit2','security1','security2'];const faqs=computed(()=>faqIds.filter(k=>(filter.value==="aiQuant.templates.filterAll"||k.startsWith(filter.value))&&t('profile.helpCenterPage.faq.'+k).toLowerCase().includes(query.value.toLowerCase())))
</script>
<template><div :class="[page==='profile'?'account-center':'account-page','account-'+page]"><RouterLink v-if="page!=='profile'" :to="path('/profile')" class="muted back-link">{{ $t("account.ui.back") }}</RouterLink><header class="account-heading" :class="{'account-banner':['referrals','promotions'].includes(page)}"><small v-if="page==='referrals'" class="page-kicker">{{t('referral.page.subtitle')}}</small><h1>{{title}}</h1><p v-if="subtitle" class="account-subtitle">{{subtitle}}</p><p v-if="page==='referrals'" class="tag-chip section-gap">{{t('referral.page.qualificationHint',{amount:'2,000'})}}</p></header>
<template v-if="page==='profile'"><section class="profile-overview"><div class="profile-identity"><Icon name="user"/><div><h2>{{ account.name }} <button :aria-label="$t(&quot;profile.editUsername&quot;)" @click="openModal('account-edit',&quot;profile.editUsername&quot;,{value:account.name,onSave:v=>account.name=v})"><Icon name="pencil"/></button></h2><p class="muted">{{ $t("UID 10000001 ") }}<button :aria-label="$t(&quot;account.ui.copyUid&quot;)" @click="copy('10000001')"><Icon name="copy"/></button></p></div></div><div class="profile-metrics"><RouterLink :to="path('/kyc')"><small>{{ $t("common.kyc") }}</small><strong>{{ $t(account.kyc==='none'?"common.kycUnverified":account.kyc==='pending'?"aiQuant.status.pending_review":"common.kycVerified") }}</strong><span class="green-link">{{ $t("margin.borrow.gate.advancedCta") }}</span></RouterLink><RouterLink :to="path('/fund-password')"><small>{{ $t("profile.securityLevel") }}</small><strong>{{ $t(security) }}</strong><div class="progress"><span :style="{width:security===&quot;auth.passwordStrengthHigh&quot;?'100%':security===&quot;auth.passwordStrengthMedium&quot;?'65%':'35%'}"></span></div><small>{{ t('profile.securityTodo',{items:[!account.fundPasswordSet?t('profile.fundPassword'):'',!account.twoFactor?t('profile.twoFactor'):''].filter(Boolean).join(' · ')}) }}</small></RouterLink><button @click="openModal('vip',&quot;profile.vipLevel&quot;)"><small>{{ $t("profile.vipLevel") }}</small><strong>{{ $t("VIP 0") }}</strong><div class="progress"><span style="width:0"></span></div><small>{{ t('profile.vip.amountToNext',{tier:1,amount:'100,000'}) }}</small></button><div><small>{{ $t("profile.creditScore") }}</small><strong>100 <span class="positive">{{ $t("profile.creditScoreLabel.good") }}</span></strong><div class="progress"><span style="width:100%"></span></div><small>{{ t('profile.creditScoreHint',{max:100}) }}</small></div></div></section><div class="profile-columns"><section class="profile-box"><header><h2>{{ $t("profile.personalSettings") }}</h2><small>{{ $t("profile.personalSettingsHint") }}</small></header><div v-for="[group,items] in [[&quot;profile.groupAccount&quot;,[[&quot;common.kyc&quot;,'/kyc',account.kyc==='none'?&quot;common.kycUnverified&quot;:&quot;aiQuant.status.pending_review&quot;,'shield'],[&quot;auth.email&quot;,'/bind-email',account.email||&quot;profile.notBound&quot;,'mail'],[&quot;auth.phone&quot;,'/bind-phone',account.phone||&quot;profile.notBound&quot;,'wallet']]],[&quot;common.security&quot;,[[&quot;profile.loginPassword&quot;,'/change-password',&quot;profile.set&quot;,'shield'],[&quot;auth.stepUp.factor.fund_password.label&quot;,'/fund-password',account.fundPasswordSet?&quot;profile.set&quot;:&quot;profile.notSet&quot;,'wallet'],[&quot;profile.twoFactor&quot;,'/2fa',account.twoFactor?&quot;common.on&quot;:&quot;common.off&quot;,'shield'],[&quot;devices.title&quot;,'/devices','','layers']]]]" :key="group" class="profile-group"><small>{{ $t(group) }}</small><RouterLink v-for="item in items" :key="item[0]" :to="path(item[1])"><Icon :name="item[3]"/><span>{{ $t(item[0]) }}</span><small>{{ $t(item[2]) }}</small><Icon name="chevron-right"/></RouterLink></div><div class="profile-group"><small>{{ $t("profile.groupPreferences") }}</small><label>{{ $t("common.language") }}<select :value="locale" @change="setLanguage($event.target.value)"><option v-for="[code,name] in languages" :value="code">{{ $t(name) }}</option></select></label><label>{{ $t("profile.fontSize") }}<select v-model="account.fontScale"><option value="standard">{{ $t("profile.fontScaleStandard") }}</option><option value="large">{{ $t("profile.fontScaleLarge") }}</option><option value="xlarge">{{ $t("profile.fontScaleXlarge") }}</option></select></label></div></section><div><section class="profile-box"><header><h2>{{ $t("profile.myBusiness") }}</h2><small>{{ $t("profile.myBusinessHint") }}</small></header><div class="profile-group"><button @click="openModal('vip',&quot;profile.vipLevel&quot;)"><Icon name="trophy"/><span>{{ $t("profile.vipLevel") }}</span><small>{{ $t("VIP 0") }}</small><Icon name="chevron-right"/></button><RouterLink v-for="[name,to,icon] in [[&quot;jointAccount.nav.menuEntry&quot;,'/joint-account','users'],[&quot;promotion.cta.invite&quot;,'/referrals','users'],[&quot;promotion.nav.menuEntry&quot;,'/promotions/tasks','trophy'],[&quot;seo.user.survey&quot;,'/survey/019e9f01-47a3-711f-9052-e7187b9f9407','layers']]" :key="to" :to="path(to)"><Icon :name="icon"/><span>{{ $t(name) }}</span><Icon name="chevron-right"/></RouterLink></div></section><section class="profile-box"><header><h2>{{ $t("profile.support") }}</h2></header><div class="profile-group"><RouterLink :to="path('/help-center')">{{ $t("common.helpCenter") }}<Icon name="chevron-right"/></RouterLink><button @click="openModal('support',&quot;common.onlineSupport&quot;)">{{ $t("aiQuant.quantFund.topUp.contactSupport") }}<Icon name="chevron-right"/></button><RouterLink :to="path('/about')">{{ $t("common.aboutUs") }}<Icon name="chevron-right"/></RouterLink></div></section><button class="secondary-button wide-button" @click="openModal('account-confirm',&quot;profile.logoutConfirmTitle&quot;,{description:&quot;profile.logoutConfirmDescription&quot;,onConfirm:()=>{logout();router.push(path('/login'))}})">{{ $t("profile.logout") }}</button></div></div></template>
<form v-else-if="isPassword" class="account-form" @submit.prevent="passwordSubmit"><label v-if="!isFund||account.fundPasswordSet">{{ $t(isFund?"profile.fundPasswordPage.oldPassword":"profile.changePassword.oldPassword") }}<input v-model="form.old" type="password" :placeholder="$t(isFund?&quot;profile.fundPasswordPage.enterOldPassword&quot;:&quot;profile.changePassword.enterOldPassword&quot;)" autocomplete="off" required/></label><label>{{ $t(isFund?"auth.stepUp.factor.fund_password.label":"auth.newPassword") }}<input v-model="form.password" type="password" :placeholder="$t(isFund?&quot;profile.fundPasswordPage.enterPassword&quot;:&quot;auth.enterNewPassword&quot;)" autocomplete="new-password" :maxlength="isFund?6:30"/></label><ul class="password-rules"><template v-if="isFund"><li :class="{positive:validPassword}">{{ $t("account.ui.exactly6Digits") }}</li></template><template v-else><li :class="{positive:form.password.length>=8&&form.password.length<=30}">{{ $t("account.ui.830Characters") }}</li><li :class="{positive:/[a-z]/i.test(form.password)}">{{ $t("auth.passwordRules.containsLetter") }}</li><li :class="{positive:/[^a-z]/i.test(form.password)}">{{ $t("auth.passwordRules.notAllLetters") }}</li><li :class="{positive:/^[A-Za-z0-9@#$*.]+$/.test(form.password)}">{{ $t("auth.passwordRules.onlyAllowedChars") }}</li></template></ul><label>{{ $t("auth.confirmPassword") }}<input v-model="form.confirm" type="password" :placeholder="$t(isFund?&quot;profile.enterFundPasswordAgain&quot;:&quot;profile.changePassword.enterConfirmPassword&quot;)" autocomplete="new-password"/></label><button class="primary-button wide-button" :disabled="!validPassword||!form.confirm">{{ $t("earn.redeem.success.done") }}</button><RouterLink class="muted center" :to="path('/forgot-password')">{{ $t("profile.changePassword.forgotPassword") }}</RouterLink></form>
<form v-else-if="isBinding" class="account-form binding-form" @submit.prevent="sent?bind():sendCode()"><label v-if="isEmail&&account.email">{{ $t("profile.bindEmailPage.currentEmailLabel") }}<input :value="account.email" disabled/></label><label>{{ $t(isEmail?"auth.email":"auth.phone") }}<input v-if="isEmail" v-model="form.email" type="email" :placeholder="$t(&quot;auth.enterEmail&quot;)" :disabled="sent"/><div v-else class="phone-input"><select v-model="form.prefix" :aria-label="$t(&quot;auth.countryCode&quot;)" :disabled="sent"><option v-for="p in ['+1','+44','+49','+33','+81','+82','+86','+852','+886','+63']" :value="p">{{ $t(p) }}</option></select><input v-model="form.phone" inputmode="tel" :placeholder="$t(&quot;auth.enterPhone&quot;)" :disabled="sent"/></div></label><template v-if="sent"><label>{{ $t("auth.verificationCode") }}<input v-model="form.code" inputmode="numeric" maxlength="6" :placeholder="$t(&quot;profile.bindEmailPage.verificationCodePlaceholder&quot;)" autocomplete="one-time-code"/></label><p class="notice">{{ $t("account.ui.localDemoCode123456") }}</p><button type="button" class="green-link" :disabled="count>0" @click="sendCode">{{ $t(count>0?t('profile.bindEmailPage.resendInSeconds',{count}):t('profile.bindEmailPage.resend')) }}</button><button type="button" class="muted" @click="sent=false">{{ $t("profile.changeFundPasswordShort") }}</button></template><button class="primary-button wide-button" :disabled="!validContact||(sent&&form.code.length!==6)">{{ t('profile.'+(isEmail?'bindEmailPage':'bindPhonePage')+'.'+(sent?((isEmail?account.email:account.phone)?'submitChange':'submitBind'):'sendCode')) }}</button></form>
<form v-else-if="page==='2fa'" class="account-form" @submit.prevent="toggle2fa"><template v-if="!account.twoFactor"><section><h3>{{ $t(t('twoFactor.step1')) }}: {{ $t(t('twoFactor.downloadApp')) }}</h3><div class="two-cols section-gap"><a class="secondary-button" href="https://apps.apple.com/app/google-authenticator/id388497605" target="_blank" rel="noopener"><img class="auth-qr" src="/newtrend/assets/auth-ios.svg" alt="iOS Google Authenticator"/>{{ $t("iOS ↗") }}</a><a class="secondary-button" href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2" target="_blank" rel="noopener"><img class="auth-qr" src="/newtrend/assets/auth-android.svg" alt="Android Google Authenticator"/>{{ $t("Android ↗") }}</a></div></section><section><h3>{{ $t(t('twoFactor.step2')) }}: {{ $t(t('twoFactor.scanOrCopy')) }}</h3><p class="notice section-gap">{{ $t("account.ui.demoKeyOnlyNotValidForARealAccount") }}</p><img class="auth-qr" src="/newtrend/assets/demo-auth.svg" alt="Local demo QR code"/><div class="demo-key">{{ $t("DEMO-LOCAL-ONLY-000000 ") }}<button type="button" :aria-label="$t(&quot;c2c.paymentAccount.copy&quot;)" @click="copy('DEMO-LOCAL-ONLY-000000')"><Icon name="layers"/></button></div><p class="muted">{{ $t("twoFactor.copyTip") }}</p></section></template><template v-else><div class="card"><Icon name="shield" green/><h3>{{ $t("common.on") }}</h3><p class="muted section-gap">{{ $t("twoFactor.2faEnabledDesc") }}</p></div></template><label>{{ $t(account.twoFactor?t('twoFactor.enterOtpToUnbind'):t('twoFactor.enterOtp')) }}<input v-model="form.code" inputmode="numeric" maxlength="6" :placeholder="$t(&quot;twoFactor.otpPlaceholder&quot;)"/></label><p class="notice">{{ $t("account.ui.localDemoCode123456") }}</p><button class="primary-button wide-button" :disabled="form.code.length!==6">{{ t('twoFactor.'+(account.twoFactor?'confirmUnbind':'confirm')) }}</button></form>
<template v-else-if="page==='devices'"><div v-if="!account.devices.length" class="empty">{{ $t("devices.empty") }}</div><article v-for="d in account.devices" :key="d.id" class="card account-device"><div class="summary-line"><div><h3>{{ d.name }}</h3><p class="muted">{{ $t(d.current?"devices.current":'') }} {{ $t(d.trusted?"devices.trusted":'') }}</p><p class="mini-label">{{ $t("Local browser · 2026-11-24") }}</p></div><Icon name="layers"/></div><div class="device-actions"><button @click="rename(d)">{{ $t("devices.rename") }}</button><button :disabled="d.trusted" @click="d.trusted=true">{{ $t("devices.trust") }}</button><button class="negative" @click="revoke(d)">{{ $t("devices.revoke") }}</button></div></article></template>
<template v-else-if="page==='kyc'"><div v-if="!id" class="two-cols section-gap"><RouterLink class="card" :to="path('/kyc/basic')"><div class="summary-line"><span class="tag-chip">{{ $t("Level 1") }}</span><span>{{ $t(account.kyc==='none'?"common.kycUnverified":account.kyc==='pending'?"aiQuant.status.pending_review":"common.kycVerified") }}</span></div><h2 class="section-gap">{{ $t("kyc.basic.title") }}</h2><p class="muted section-gap">{{ $t("kyc.basic.description") }}</p><span class="green-link section-gap">{{ $t("c2c.common.goKyc") }}</span></RouterLink><div class="card"><span class="tag-chip">{{ $t("Level 2") }}</span><h2 class="section-gap">{{ $t("kyc.advanced.title") }}</h2><p class="muted section-gap">{{ $t("kyc.advanced.description") }}</p><RouterLink v-if="account.kyc==='approved'" class="green-link section-gap" :to="path('/kyc/advanced')">{{ $t("kyc.advanced.cta") }}</RouterLink><p v-else class="mini-label section-gap">{{ $t("kyc.advanced.lockedHint") }}</p></div></div><div v-else-if="(id==='basic'?account.kyc:account.advanced)==='pending'" class="card section-gap"><h2>{{ $t("aiQuant.status.pending_review") }}</h2><p class="muted section-gap">{{ $t(t('kyc.pendingTip')) }}</p><p class="mini-label section-gap">{{ $t(t('kyc.pendingHint')) }}</p></div><div v-else-if="id==='advanced'&&account.kyc!=='approved'" class="notice section-gap">{{ $t(t('kyc.advanced.lockedHint')) }}</div><form v-else class="account-form" @submit.prevent="step===1&&id==='basic'?nextKyc():submitKyc()"><div v-if="id==='basic'" class="kyc-steps"><span :class="{active:step===1}">{{ $t("account.ui.1PersonalInformation") }}</span><span :class="{active:step===2}">{{ $t("account.ui.2UploadDocuments") }}</span></div><template v-if="step===1&&id==='basic'"><label>{{ $t("kyc.fullName") }}<input v-model="form.fullName" :placeholder="$t(&quot;kyc.enterFullName&quot;)"/></label><label>{{ $t("kyc.idType") }}<select v-model="form.idType"><option disabled value="">{{ $t("kyc.selectIdType") }}</option><option :value="&quot;kyc.idCard&quot;">{{ $t("kyc.idCard") }}</option><option :value="&quot;kyc.passport&quot;">{{ $t("kyc.passport") }}</option><option :value="&quot;kyc.driverLicense&quot;">{{ $t("kyc.driverLicense") }}</option></select></label><label>{{ $t("kyc.idNumber") }}<input v-model="form.idNumber" :placeholder="$t(&quot;kyc.enterIdNumber&quot;)"/></label><label>{{ $t("kyc.country") }}<select v-model="form.country"><option disabled value="">{{ $t("kyc.enterCountry") }}</option><option v-for="c in ['United States','United Kingdom','Taiwan','Hong Kong','China','Japan','Korea','Germany','France','Philippines','Singapore']" :value="c">{{ $t(c) }}</option></select></label><button class="primary-button wide-button">{{ $t("kyc.nextStep") }}</button></template><template v-else><p class="notice">{{ $t("account.ui.useFictionalDetailsAndDemoImagesFilesStayOn") }}</p><label v-for="[key,label] in id==='basic'?[['front',&quot;kyc.idFront&quot;],['back',&quot;kyc.idBack&quot;],['selfie',&quot;kyc.selfie&quot;]]:[['handheld',&quot;kyc.advanced.handheldLabel&quot;],['proof',&quot;kyc.advanced.assetProofTitle&quot;]]" :key="key">{{ $t(label) }}<span class="upload-box"><Icon name="layers"/>{{ files[key]||t('kyc.clickToUpload') }}<input type="file" accept="image/png,image/jpeg,application/pdf" :aria-label="$t(label)" @change="selectFile(key,$event)"/></span></label><button v-if="id==='basic'" type="button" class="secondary-button" @click="step=1">{{ $t("aiQuant.quantFund.interestRecords.back") }}</button><button class="primary-button wide-button">{{ $t("kyc.submit") }}</button></template></form></template>
<template v-else-if="page==='referrals'"><form class="card referral-bind section-gap" @submit.prevent="submitReferral"><h2><Icon name="users" green/>{{t('referral.bind.title')}}</h2><p class="muted">{{t('referral.bind.description')}}</p><div class="referral-bind-input"><input v-model="form.referral" :placeholder="t('referral.bind.placeholder')" :aria-label="t('referral.bind.title')" :disabled="!!account.referrer"/><button class="primary-button" :disabled="!!account.referrer||!form.referral.trim()">{{account.referrer?t('referral.bind.success'):t('referral.bind.submit')}}</button></div></form><div class="referral-stats section-gap"><section class="card referral-code"><h2>{{t('referral.code.title')}}</h2><div class="summary-line"><strong>DEMO10001</strong><button class="secondary-button" @click="copy('DEMO10001')">{{t('referral.code.copy')}}</button></div></section><section v-for="key in ['totalInvited','qualifiedCount','rewardedCount','totalAccumulated']" :key="key" class="card"><small>{{t('referral.stats.'+key)}}</small><p><strong>0</strong><small v-if="key==='totalAccumulated'"> USDT</small></p></section></div><section class="card referral-share section-gap"><h2>{{t('referral.shareLink.title')}}</h2><p class="muted">{{t('referral.shareLink.description')}}</p><div class="referral-share-content"><img v-if="referralQr" :src="referralQr" :alt="t('referral.shareLink.qrAlt')"/><div><div class="demo-key">{{locationOrigin+'/newtrend'+path('/register')+'?ref=DEMO10001'}}</div><div class="summary-line"><small class="muted">{{t('referral.shareLink.scanHint')}}</small><button class="secondary-button" @click="copy(locationOrigin+'/newtrend'+path('/register')+'?ref=DEMO10001')">{{t('referral.shareLink.copy')}}</button></div></div></div></section><section class="card referral-invitees section-gap"><h2>{{t('referral.invitees.title')}}</h2><div class="empty"><Icon name="users"/><h3>{{t('referral.empty.title')}}</h3><p>{{t('referral.empty.description')}}</p></div></section></template>
<template v-else-if="page==='joint-account'"><template v-if="step===2"><div class="card section-gap"><h2>{{ $t(t('jointAccount.apply.kycRequiredTitle')) }}</h2><p class="muted section-gap">{{ $t(t('jointAccount.apply.kycRequiredDesc')) }}</p><div class="device-actions"><button class="secondary-button" @click="step=1">{{ $t("aiQuant.create.cancel") }}</button><RouterLink class="primary-button" :to="path('/kyc')">{{ $t("c2c.common.goKyc") }}</RouterLink></div></div></template><form v-else-if="step===3" class="account-form" @submit.prevent="submitJoint"><label>{{ $t("jointAccount.apply.relationshipType") }}<select v-model="form.relationship"><option disabled value="">{{ $t("c2c.quotes.select") }}</option><option v-for="r in [&quot;jointAccount.relationship.spouse&quot;,&quot;jointAccount.relationship.family&quot;,&quot;jointAccount.relationship.partner&quot;,&quot;jointAccount.relationship.agent&quot;]" :value="r">{{ $t(r) }}</option></select></label><label>{{ $t("jointAccount.apply.memberUid") }}<input v-model="form.uid" :placeholder="$t(&quot;jointAccount.apply.memberUidPlaceholder&quot;)" inputmode="numeric"/></label><label>{{ $t("jointAccount.apply.proofSection") }}<input type="file" accept="image/jpeg,image/png,application/pdf" @change="selectFile('relationship',$event)"/></label><p class="notice">{{ $t("account.ui.thisDemoDoesNotOpenARealJointAccount") }}</p><button class="primary-button">{{ $t("jointAccount.apply.submit") }}</button><button type="button" class="secondary-button" @click="step=1">{{ $t("aiQuant.create.cancel") }}</button></form><template v-else><div class="joint-holder card section-gap"><small>{{ $t("jointAccount.holder.title") }}</small><div class="two-cols section-gap"><div><h2>{{ account.name }}</h2><p class="mini-label">{{ $t("account.ui.primaryApplicantYou") }}</p></div><div><h2 class="muted">{{ $t(account.joint?account.joint.uid:"jointAccount.holder.vacant") }}</h2><p class="mini-label">{{ $t("jointAccount.apply.memberSection") }}</p></div></div></div><ul class="joint-points"><li v-for="k in ['ownership','switch','exit']">{{ $t(t('jointAccount.intro.points.'+k)) }}</li></ul><p v-if="account.joint" class="notice">{{ $t(t('jointAccount.application.title.pending_consent')) }}</p><button v-else class="primary-button" @click="applyJoint">{{ $t("jointAccount.apply.start") }}</button><p class="mini-label section-gap">{{ $t(t('jointAccount.intro.prepare')) }}<br/>{{ $t(t('jointAccount.intro.kycOnly')) }}</p><details v-for="k in ['memberCan','memberSteps','dissolve']" :key="k" class="account-faq"><summary>{{ $t(t('jointAccount.faq.'+k+'.q')) }}</summary><p>{{ $t(t('jointAccount.faq.'+k+'.a')) }}</p></details></template></template>
<template v-else-if="page==='promotions'"><div class="empty"><Icon name="trophy"/><h2>{{ $t(t('promotion.empty.title')) }}</h2><p>{{ $t(t('promotion.empty.description')) }}</p></div></template>
<template v-else-if="page==='survey'"><Survey/></template>
<template v-else-if="page==='help-center'"><input v-model="query" :placeholder="$t(t('profile.helpCenterPage.searchPlaceholder'))" :aria-label="$t(t('profile.helpCenterPage.searchPlaceholder'))" class="wide-button section-gap"/><div class="filter-row"><button v-for="[key,label] in [[&quot;aiQuant.templates.filterAll&quot;,&quot;aiQuant.templates.filterAll&quot;],['account',&quot;profile.helpCenterPage.categories.account&quot;],['trade',&quot;profile.helpCenterPage.categories.trade&quot;],['deposit',&quot;profile.helpCenterPage.categories.deposit&quot;],['security',&quot;profile.helpCenterPage.categories.security&quot;]]" :class="{active:filter===key}" @click="filter=key">{{ $t(label) }}</button></div><details v-for="key in faqs" :key="key" class="account-faq"><summary>{{ $t(t('profile.helpCenterPage.faq.'+key)) }}</summary><p>{{ $t(t('profile.helpCenterPage.faq.'+key+'Answer')) }}</p></details><p v-if="!faqs.length" class="empty">{{ $t(t('profile.helpCenterPage.empty',{query})) }}</p></template>
<p v-if="error" class="form-error section-gap" role="alert">{{ $t(error) }}</p><p v-if="success" class="form-success section-gap" role="status">{{ $t(success) }}</p></div></template>
